try { processPayment('cust_1', -5, 'USD'); console.log('Negative amount: FAIL (no throw)'); } catch(e) { console.log('Negative amount:', e.message === 'Invalid payment amount' ? 'PASS' : 'FAIL: ' + e.message); }

// Test: amount exceeds limit
try { processPayment('cust_1', 10001, 'USD'); console.log('Over limit: FAIL (no throw)'); } catch(e) { console.log('Over limit:', e.message === 'Amount exceeds limit' ? 'PASS' : 'FAIL: ' + e.message); }

